// Writes public/js/firebase-config.js, the Firebase web config the site imports, from .env or the environment.
// The generated file is git-ignored, so the repo never holds the values. It runs before `npm run dev` and, through
// hosting.predeploy in firebase.json, before every deploy. It names any missing variables but never prints a value.
// Usage: node scripts/build-config.mjs   (or: npm run config)
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { parseEnv } from 'node:util';

const here = (path) => fileURLToPath(new URL(path, import.meta.url));

// Config key -> variable name. The MV_ prefix keeps an unrelated FIREBASE_* variable in your shell from being picked up.
const VARS = {
  apiKey: 'MV_FIREBASE_API_KEY',
  authDomain: 'MV_FIREBASE_AUTH_DOMAIN',
  projectId: 'MV_FIREBASE_PROJECT_ID',
  storageBucket: 'MV_FIREBASE_STORAGE_BUCKET',
  messagingSenderId: 'MV_FIREBASE_MESSAGING_SENDER_ID',
  appId: 'MV_FIREBASE_APP_ID',
};

// Variables already set in the environment win over .env, so CI can supply them without a file.
const envPath = here('../.env');
const fileVars = existsSync(envPath) ? parseEnv(readFileSync(envPath, 'utf8')) : {};
const config = Object.fromEntries(
  Object.entries(VARS).map(([key, name]) => [key, (process.env[name] || fileVars[name] || '').trim()]),
);

const missing = Object.entries(VARS)
  .filter(([key]) => !config[key])
  .map(([, name]) => name);
if (missing.length) {
  console.error(`Firebase config is incomplete. Set ${missing.join(', ')} in .env (copy .env.example) or in the environment.`);
  process.exit(1);
}

// Guard against a .env copied from another project: the config must belong to the project this repo deploys to.
const rcPath = here('../.firebaserc');
if (existsSync(rcPath)) {
  const deployProject = JSON.parse(readFileSync(rcPath, 'utf8')).projects?.default;
  if (deployProject && deployProject !== config.projectId) {
    console.error('MV_FIREBASE_PROJECT_ID does not match the default project in .firebaserc; not writing the config.');
    process.exit(1);
  }
}

const fields = Object.entries(config)
  .map(([key, value]) => `  ${key}: ${JSON.stringify(value)},`)
  .join('\n');
writeFileSync(
  here('../public/js/firebase-config.js'),
  `// Generated by scripts/build-config.mjs from .env. Not committed; run \`npm run config\` to rebuild.\nexport const firebaseConfig = {\n${fields}\n};\n`,
);
console.log('wrote public/js/firebase-config.js');
